<script setup lang="ts">
import WalletCustomerProofHistory from '../proof/WalletCustomerProofHistory.vue'
import WalletCustomerPayNowProof from '../proof/WalletCustomerPayNowProof.vue'
import {channelType,channelLabel,topupChannelName} from '../collectionMethods'
import { useI18n } from 'vue-i18n'
import { useCustomerTopups } from '../useCustomerTopups'
import { dateTime } from '../format'
import WalletTopupOffers from '../components/WalletTopupOffers.vue'
import WalletAmountSplit from '../components/WalletAmountSplit.vue'
import WalletQrDisplay from '../components/WalletQrDisplay.vue'
const {t}=useI18n(),{home,offer,task,offers,selected,channel,quote,expired,canApply,active,qr,note,timezone,apply,action,show,showQr}=useCustomerTopups()
</script>
<template><section class="wallet-page-heading"><h2>{{t('wallet.marketing.applications')}}</h2><button :disabled="task.busy.value" @click="offer.refresh()">{{t('wallet.refresh')}}</button></section><p v-if="task.error.value||offer.error.value" class="wallet-error" role="alert">{{task.error.value||offer.error.value}}</p><p v-if="task.busy.value" role="status">{{t('wallet.loading')}}</p><p class="wallet-warning">{{t('wallet.marketing.pending')}}</p><section v-if="home?.context.transactionsEnabled&&offers?.selfServiceEnabled!==false" class="wallet-form"><WalletTopupOffers v-model:selected="selected" v-model:channel="channel" confirm-only :offers="offers" :quote="quote" :expired="expired" :busy="offer.busy.value||task.busy.value" :timezone="timezone" :paynow-configured="home.context.paynowConfigured" @quote="offer.getQuote" /><button class="wallet-primary" :disabled="task.busy.value||offer.busy.value||!canApply" @click="apply">{{t('wallet.marketing.apply')}}</button><button :disabled="offer.busy.value||task.busy.value" @click="offer.refresh">{{t('wallet.refresh')}}</button></section><p v-else class="wallet-empty">{{t('wallet.marketing.unavailable')}}</p>
<section v-if="active" class="wallet-card"><h3>{{t(`wallet.states.${active.status}`)}}</h3><WalletAmountSplit :principal="active.principalCents??active.amountCents" :bonus="active.bonusCents??0" :total="active.creditTotalCents??active.amountCents" /><p>{{channelLabel(t,active.channel,undefined,topupChannelName(active))}}</p><p>{{t('wallet.marketing.origin')}}: {{t(`wallet.marketing.${active.origin??'legacy_no_campaign'}`)}}</p><p v-if="active.customerDeclaredPaidAt">{{t('wallet.marketing.declared')}} 路 {{dateTime(active.customerDeclaredPaidAt,timezone)}}</p><template v-if="active.status==='pending_collection'"><p>{{channelType(active.channel)==='other'?t('wallet.operation.otherCollectionHint'):t(`wallet.marketing.${channelType(active.channel)==='cash'?'cashHint':channelType(active.channel)==='credit_card'?'cardHint':'paynowHint'}`)}}</p><button v-if="channelType(active.channel)==='paynow'" :disabled="task.busy.value" @click="showQr">{{t('wallet.showPaynow')}}</button><WalletQrDisplay v-if="qr" :value="qr" /><WalletCustomerPayNowProof v-if="channelType(active.channel)==='paynow'" :store="active.storeId" source-type="topup" :source-id="active.id" :channel="active.channel" :amount="(active.amountCents/100).toFixed(2)" @submitted="show(active)" /><label>{{t('wallet.marketing.paymentNote')}}<textarea v-model.trim="note" maxlength="500" /></label><button :disabled="task.busy.value" @click="action('declare-paid')">{{t('wallet.marketing.declare')}}</button><button :disabled="task.busy.value" @click="action('cancel')">{{t('wallet.cancel')}}</button></template><WalletCustomerProofHistory v-if="active.status!=='pending_collection'" :store="active.storeId" source-type="topup" :source-id="active.id" /><small>{{active.id}}</small></section></template>
